```sql
SELECT a.AirportCode, a.AirportName, a.City
FROM airports a
WHERE NOT EXISTS (
    SELECT 1 FROM flights f WHERE f.SourceAirport = a.AirportCode
)
AND NOT EXISTS (
    SELECT 1 FROM flights f WHERE f.DestAirport = a.AirportCode
);
```

